INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (1, 0, 1, 1, 2, 1, "アヤネ", "", "---", "");
INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (2, 6000, 0, 1, 1, 3, "アサヒ", "逆境に屈することなく、部員たちを引っ張る主将。ミート力を活かした安定感のある打撃が持ち味。", "---", "");
INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (3, 16000, 3, 1, 3, 0, "部員3", "無愛想だが仲間を大切に想う気持ちは誰よりも強い男。ケンカで鍛えた腕っぷしが自慢のパワーヒッター。", "アドレナリン", "ホームランを連発すると、連発数に応じてパワーアップする");
INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (4, 30000, 2, 1, 2, 2, "{0}", "みんなからの厚い信頼を集める期待の助っ人部員。実力は未知数だが幸運なハプニングを呼び込む。", "ラッキー", "幸運のハプニングを呼び込む");
INSERT INTO `v1_1199eb7bc655b4a37b7fe856fdf6f90a0d306306dfee3c7c7b2b3e4cd3de4a53` VALUES (5, 50000, 1, 0, 0, 1, "選手名鑑 おまけページ", "みんなの知らない極秘情報がのっているおまけページ。決して誰かに見せてはいけない。", "", "");
